/**
 * A basic smoke test that ensures there is no crash at pipeline construction time.
 */
@Test
public void testMinimalWordCountJava8() {
    Pipeline p = TestPipeline.create();
    p.apply(TextIO.Read.from("gs://dataflow-samples/shakespeare/*")).apply(FlatMapElements.via((String word) -> Arrays.asList(word.split("[^a-zA-Z']+"))).withOutputType(new TypeDescriptor<String>() {
    })).apply(Filter.byPredicate((String word) -> !word.isEmpty())).apply(Count.<String>perElement()).apply(MapElements.via((KV<String, Long> wordCount) -> wordCount.getKey() + ": " + wordCount.getValue()).withOutputType(new TypeDescriptor<String>() {
