    s = new Seeker(marker);
    buffer = new byte[] { 0, 0, 0, 1 };
    assertEquals(-1, s.find(buffer, 3));
    s = new Seeker(marker);
    buffer = new byte[] { 0, 0 };
    assertEquals(-1, s.find(buffer, 1));
    buffer = new byte[] { 1, 0 };
    assertEquals(-1, s.find(buffer, 1));
    s = new Seeker(marker);
    buffer = new byte[] { 0, 2 };
    assertEquals(-1, s.find(buffer, 1));
    buffer = new byte[] { 0, 2 };
    assertEquals(-1, s.find(buffer, 1));
