@Test
@SuppressWarnings("rawtypes")
public void testArrays() {
    String[] args = new String[] { "--boolean=true", "--boolean=true", "--boolean=false", "--char=d", "--char=e", "--char=f", "--short=300", "--short=301", "--short=302", "--int=100000", "--int=100001", "--int=100002", "--long=123890123890", "--long=123890123891", "--long=123890123892", "--float=55.5", "--float=55.6", "--float=55.7", "--double=12.3", "--double=12.4", "--double=12.5", "--string=stringValue1", "--string=stringValue2", "--string=stringValue3", "--classValue=" + PipelineOptionsFactory.class.getName(), "--classValue=" + PipelineOptionsFactoryTest.class.getName(), "--enum=" + TestEnum.Value, "--enum=" + TestEnum.Value2 };
    Arrays options = PipelineOptionsFactory.fromArgs(args).as(Arrays.class);
    boolean[] bools = options.getBoolean();
    assertTrue(bools[0] && bools[1] && !bools[2]);
    assertArrayEquals(new char[] { 'd', 'e', 'f' }, options.getChar());
    assertArrayEquals(new short[] { 300, 301, 302 }, options.getShort());
    assertArrayEquals(new int[] { 100000, 100001, 100002 }, options.getInt());
    assertArrayEquals(new long[] { 123890123890L, 123890123891L, 123890123892L }, options.getLong());
    assertArrayEquals(new float[] { 55.5f, 55.6f, 55.7f }, options.getFloat(), 0.0f);
    assertArrayEquals(new double[] { 12.3, 12.4, 12.5 }, options.getDouble(), 0.0);
    assertArrayEquals(new String[] { "stringValue1", "stringValue2", "stringValue3" }, options.getString());
    assertArrayEquals(new Class[] { PipelineOptionsFactory.class, PipelineOptionsFactoryTest.class }, options.getClassValue());
    assertArrayEquals(new TestEnum[] { TestEnum.Value, TestEnum.Value2 }, options.getEnum());
}

