    // We know that the underlying reader behaves correctly (because of the previous test),
    // now check that we are wrapping it correctly.
    DataflowPipelineOptions options = PipelineOptionsFactory.create().as(DataflowPipelineOptions.class);
    Reader<WindowedValue<Integer>> reader = (Reader<WindowedValue<Integer>>) ReaderFactory.Registry.defaultRegistry().create(translateIOToCloudSource(TestIO.fromRange(10, 20), options), options, // executionContext
