        assertEquals(valueInGlobalWindow(10), iterator.next());
        assertEquals(0.1, readerProgressToCloudProgress(iterator.getProgress()).getPercentComplete().doubleValue(), 1e-6);
        assertEquals(valueInGlobalWindow(11), iterator.next());
        assertEquals(0.2, readerProgressToCloudProgress(iterator.getProgress()).getPercentComplete().doubleValue(), 1e-6);
        assertEquals(valueInGlobalWindow(12), iterator.next());
