@Test
public void testReadUnboundedReader() throws Exception {
    StreamingModeExecutionContext context = new StreamingModeExecutionContext("stageName", new ConcurrentHashMap<ByteString, ReaderCacheEntry>(), null);
    DataflowPipelineOptions options = PipelineOptionsFactory.create().as(DataflowPipelineOptions.class);
    options.setNumWorkers(5);
    ByteString state = ByteString.EMPTY;
    for (int i = 0; i < 100; ) /* Incremented in inner loop */
    {
        WindowedValue<ValueWithRecordId<KV<Integer, Integer>>> value;
        // Initialize streaming context with state from previous iteration.
        context.start(Windmill.WorkItem.newBuilder().setKey(// key is zero-padded index.
        ByteString.copyFromUtf8("0000000000000001")).setWorkToken(// Required proto field, unused.
        0).setSourceState(// Source state.
        Windmill.SourceState.newBuilder().setState(state).build()).build(), new Instant(0), // StateReader
        null, // StateFetcher
        null, Windmill.WorkItemCommitRequest.newBuilder());
        @SuppressWarnings({ "unchecked", "rawtypes" })
        Reader<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> reader = (Reader) CustomSources.create((CloudObject) CustomSources.serializeToCloudSource(new CountingSource(Integer.MAX_VALUE), options).getSpec(), options, context);
        Reader.ReaderIterator<WindowedValue<ValueWithRecordId<KV<Integer, Integer>>>> iterator = reader.iterator();
        // Verify data.
        while (iterator.hasNext()) {
            value = iterator.next();
            assertEquals(KV.of(0, i), value.getValue().getValue());
            assertArrayEquals(encodeToByteArray(KvCoder.of(VarIntCoder.of(), VarIntCoder.of()), KV.of(0, i)), value.getValue().getId());
            assertThat(value.getWindows(), contains((BoundedWindow) GlobalWindow.INSTANCE));
            assertEquals(i, value.getTimestamp().getMillis());
            i++;
        }
        // Extract and verify state modifications.
        context.flushState();
        state = context.getOutputBuilder().getSourceStateUpdates().getState();
        // CountingSource's watermark is the last record - 1.  i is now one past the last record,
        // so the expected watermark is i-2 millis.
        assertEquals(TimeUnit.MILLISECONDS.toMicros(i - 2), context.getOutputBuilder().getSourceWatermark());
        assertEquals(1, context.getOutputBuilder().getSourceStateUpdates().getFinalizeIdsList().size());
        assertNotNull(context.getCachedReader());
        Windmill.Counter backlog = getCounter(context, "dataflow_backlog_size-stageName");
        assertEquals(7L, backlog.getIntScalar());
        assertTrue(backlog.getCumulative());
        assertEquals(Windmill.Counter.Kind.SUM, backlog.getKind());
    }
}

