@Test
public void testSettingOfSdkPipelineOptions() throws IOException {
    DataflowPipelineOptions options = buildPipelineOptions();
    options.setRunner(DataflowPipelineRunner.class);
    Pipeline p = buildPipeline(options);
    p.traverseTopologically(new RecordingPipelineVisitor());
    Job job = DataflowPipelineTranslator.fromOptions(options).translate(p, Collections.<DataflowPackage>emptyList()).getJob();
    // Note that the contents of this materialized map may be changed by the act of reading an
    // option, which will cause the default to get materialized whereas it would otherwise be
    // left absent. It is permissible to simply alter this test to reflect current behavior.
    assertEquals(ImmutableMap.of("options", ImmutableMap.builder().put("appName", "DataflowPipelineTranslatorTest").put("project", "some-project").put("pathValidatorClass", "com.google.cloud.dataflow.sdk.util.DataflowPathValidator").put("runner", "com.google.cloud.dataflow.sdk.runners.DataflowPipelineRunner").put("jobName", "some-job-name").put("tempLocation", "gs://somebucket/some/path").put("stagingLocation", "gs://somebucket/some/path/staging").put("stableUniqueNames", "WARNING").put("streaming", false).put("numberOfWorkerHarnessThreads", 0).build()), job.getEnvironment().getSdkPipelineOptions());
}

