    Object[] expectedReceivedElems1 = { WindowedValue.valueInGlobalWindow("tag1: started"), WindowedValue.valueInGlobalWindow("tag1: processing: 3"), WindowedValue.valueInGlobalWindow("tag1: processing: 42"), WindowedValue.valueInGlobalWindow("tag1: processing: 666"), WindowedValue.valueInGlobalWindow("tag1: finished") };
    assertArrayEquals(expectedReceivedElems1, receiver1.receivedElems.toArray());
    Object[] expectedReceivedElems2 = { WindowedValue.valueInGlobalWindow("tag2: started"), WindowedValue.valueInGlobalWindow("tag2: processing: 3"), WindowedValue.valueInGlobalWindow("tag2: processing: 42"), WindowedValue.valueInGlobalWindow("tag2: processing: 666"), WindowedValue.valueInGlobalWindow("tag2: finished") };
    assertArrayEquals(expectedReceivedElems2, receiver2.receivedElems.toArray());
    Object[] expectedReceivedElems3 = { WindowedValue.valueInGlobalWindow("tag3: started"), WindowedValue.valueInGlobalWindow("tag3: processing: 3"), WindowedValue.valueInGlobalWindow("tag3: processing: 42"), WindowedValue.valueInGlobalWindow("tag3: processing: 666"), WindowedValue.valueInGlobalWindow("tag3: finished") };
