@Test
public void testFetchGlobalDataBasic() throws Exception {
    StateFetcher fetcher = new StateFetcher(server);
    ByteString.Output stream = ByteString.newOutput();
    ListCoder.of(WindowedValue.getFullCoder(StringUtf8Coder.of(), GlobalWindow.Coder.INSTANCE)).encode(Arrays.asList(WindowedValue.valueInGlobalWindow("data")), stream, Coder.Context.OUTER);
    ByteString encodedIterable = stream.toByteString();
    PCollectionView<String> view = TestPipeline.create().apply(Create.<String>of().withCoder(StringUtf8Coder.of())).apply(View.<String>asSingleton());
    String tag = view.getTagInternal().getId();
    // Test three calls in a row. First, data is not ready, then data is ready,
    // then the data is already cached.
    when(server.getSideInputData(any(Windmill.GetDataRequest.class))).thenReturn(buildGlobalDataResponse(tag, ByteString.EMPTY, false, null), buildGlobalDataResponse(tag, ByteString.EMPTY, true, encodedIterable));
    assertEquals(null, fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    assertEquals(null, fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    assertEquals("data", fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.KNOWN_READY, readStateSupplier));
    assertEquals("data", fetcher.fetchSideInput(view, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.KNOWN_READY, readStateSupplier));
    verify(server, times(2)).getSideInputData(buildGlobalDataRequest(tag, ByteString.EMPTY));
    verifyNoMoreInteractions(server);
}

@Test
public void testFetchGlobalDataCacheOverflow() throws Exception {
    Coder<List<WindowedValue<String>>> coder = ListCoder.of(WindowedValue.getFullCoder(StringUtf8Coder.of(), GlobalWindow.Coder.INSTANCE));
    ByteString.Output stream = ByteString.newOutput();
    coder.encode(Arrays.asList(WindowedValue.valueInGlobalWindow("data1")), stream, Coder.Context.OUTER);
    ByteString encodedIterable1 = stream.toByteString();
    stream = ByteString.newOutput();
    coder.encode(Arrays.asList(WindowedValue.valueInGlobalWindow("data2")), stream, Coder.Context.OUTER);
    ByteString encodedIterable2 = stream.toByteString();
    Cache<StateFetcher.SideInputId, StateFetcher.SideInputCacheEntry> cache = CacheBuilder.newBuilder().build();
    StateFetcher fetcher = new StateFetcher(server, cache);
    PCollectionView<String> view1 = TestPipeline.create().apply(Create.<String>of().withCoder(StringUtf8Coder.of())).apply(View.<String>asSingleton());
    PCollectionView<String> view2 = TestPipeline.create().apply(Create.<String>of().withCoder(StringUtf8Coder.of())).apply(View.<String>asSingleton());
    String tag1 = view1.getTagInternal().getId();
    String tag2 = view2.getTagInternal().getId();
    // Test four calls in a row. First, fetch view1, then view2 (which evicts view1 from the cache),
    // then view 1 again twice.
    when(server.getSideInputData(any(Windmill.GetDataRequest.class))).thenReturn(buildGlobalDataResponse(tag1, ByteString.EMPTY, true, encodedIterable1), buildGlobalDataResponse(tag2, ByteString.EMPTY, true, encodedIterable2), buildGlobalDataResponse(tag1, ByteString.EMPTY, true, encodedIterable1));
    assertEquals("data1", fetcher.fetchSideInput(view1, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    assertEquals("data2", fetcher.fetchSideInput(view2, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    cache.invalidateAll();
    assertEquals("data1", fetcher.fetchSideInput(view1, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    assertEquals("data1", fetcher.fetchSideInput(view1, GlobalWindow.INSTANCE, STATE_FAMILY, SideInputState.UNKNOWN, readStateSupplier));
    ArgumentCaptor<Windmill.GetDataRequest> captor = ArgumentCaptor.forClass(Windmill.GetDataRequest.class);
    verify(server, times(3)).getSideInputData(captor.capture());
    verifyNoMoreInteractions(server);
    assertThat(captor.getAllValues(), contains(buildGlobalDataRequest(tag1, ByteString.EMPTY), buildGlobalDataRequest(tag2, ByteString.EMPTY), buildGlobalDataRequest(tag1, ByteString.EMPTY)));
}

