@Test
public void testExceptions() throws Exception {
    List<ParallelInstruction> instructions = Arrays.asList(makeSourceInstruction(StringUtf8Coder.of()), makeDoFnInstruction(new TestExceptionFn(), 0, StringUtf8Coder.of()), makeSinkInstruction(StringUtf8Coder.of(), 1));
    FakeWindmillServer server = new FakeWindmillServer();
    server.setExpectedExceptionCount(1);
    server.addWorkToOffer(buildInput("work {" + "  computation_id: \"" + DEFAULT_COMPUTATION_ID + "\"" + "  work {" + "    key: \"" + keyStringForIndex(0) + "\"" + "    work_token: 0" + "    message_bundles {" + "      source_computation_id: \"" + DEFAULT_SOURCE_COMPUTATION_ID + "\"" + "      messages {" + "        timestamp: 0" + "        data: \"0\"" + "      }" + "    }" + "  }" + "}", CoderUtils.encodeToByteArray(CollectionCoder.of(IntervalWindow.getCoder()), Arrays.asList(DEFAULT_WINDOW))));
    StreamingDataflowWorker worker = new StreamingDataflowWorker(Arrays.asList(defaultMapTask(instructions)), server, createTestingPipelineOptions());
    worker.start();
    Windmill.Exception exception = server.getException();
    assertThat(exception.getStackFrames(0), containsString("Another exception!"));
    assertThat(exception.getStackFrames(1), containsString("processElement"));
    assertTrue(exception.hasCause());
    assertThat(exception.getCause().getStackFrames(0), containsString("Exception!"));
    assertThat(exception.getCause().getStackFrames(1), containsString("processElement"));
    assertFalse(exception.getCause().hasCause());
    // The server should retry the work since reporting the exception succeeded.
    // Make next retry should fail because we only expected 1 exception.
    exception = server.getException();
}

