@Test
public void testMergeWindows() throws Exception {
    Coder<KV<String, String>> kvCoder = KvCoder.of(StringUtf8Coder.of(), StringUtf8Coder.of());
    Coder<WindowedValue<KV<String, String>>> windowedKvCoder = FullWindowedValueCoder.of(kvCoder, IntervalWindow.getCoder());
    KvCoder<String, List<String>> groupedCoder = KvCoder.of(StringUtf8Coder.of(), ListCoder.of(StringUtf8Coder.of()));
    Coder<WindowedValue<KV<String, List<String>>>> windowedGroupedCoder = FullWindowedValueCoder.of(groupedCoder, IntervalWindow.getCoder());
    CloudObject spec = CloudObject.forClassName("MergeWindowsDoFn");
    addString(spec, PropertyNames.SERIALIZED_FN, StringUtils.byteArrayToJsonString(SerializableUtils.serializeToByteArray(WindowingStrategy.of(FixedWindows.of(Duration.standardSeconds(1))))));
    addObject(spec, PropertyNames.INPUT_CODER, windowedKvCoder.asCloudObject());
    ParallelInstruction mergeWindowsInstruction = new ParallelInstruction().setSystemName("MergeWindows-System").setName("MergeWindowsStep").setParDo(new ParDoInstruction().setInput(new InstructionInput().setProducerInstructionIndex(0).setOutputNum(0)).setNumOutputs(1).setUserFn(spec)).setOutputs(Arrays.asList(new InstructionOutput().setName("output").setCodec(windowedGroupedCoder.asCloudObject())));
    List<ParallelInstruction> instructions = Arrays.asList(makeWindowingSourceInstruction(kvCoder), mergeWindowsInstruction, makeSinkInstruction(groupedCoder, 1));
    FakeWindmillServer server = new FakeWindmillServer();
    StreamingDataflowWorker worker = new StreamingDataflowWorker(Arrays.asList(defaultMapTask(instructions)), server, createTestingPipelineOptions());
    Map<String, String> nameMap = new HashMap<>();
    nameMap.put("MergeWindowsStep", "MergeWindows");
    worker.addStateNameMappings(nameMap);
    worker.start();
    server.addWorkToOffer(buildInput("work {" + "  computation_id: \"" + DEFAULT_COMPUTATION_ID + "\"" + "  input_data_watermark: 0" + "  work {" + "    key: \"" + DEFAULT_KEY_STRING + "\"" + "    work_token: 0" + "    message_bundles {" + "      source_computation_id: \"" + DEFAULT_SOURCE_COMPUTATION_ID + "\"" + "      messages {" + "        timestamp: 0" + "        data: \"" + dataStringForIndex(0) + "\"" + "      }" + "    }" + "  }" + "}", windowAtZeroBytes()));
    Map<Long, Windmill.WorkItemCommitRequest> result = server.waitForAndGetCommits(1);
    // These tags and data are opaque strings and this is a change detector test.
    String window = "/gAAAAAAAA-joBw/";
    // GC timer just has window
    ByteString timerTag = ByteString.copyFromUtf8(window + "+0:999");
    ByteString bufferTag = ByteString.copyFromUtf8(window + "+sbuf");
    ByteString paneInfoTag = ByteString.copyFromUtf8(window + "+spane");
    ByteString watermarkHoldTag = ByteString.copyFromUtf8(window + "+shold");
    String stateFamily = "MergeWindows";
    ByteString bufferData = ByteString.copyFromUtf8("\000data0");
    ByteString outputData = ByteString.copyFromUtf8("\000\000\000\001\005data0");
    // These values are not essential to the change detector test
    long timerTimestamp = 999000L;
    WorkItemCommitRequest actualOutput = result.get(0L);
    // Set timer
    assertThat(actualOutput.getOutputTimersList(), Matchers.contains(Matchers.equalTo(Windmill.Timer.newBuilder().setTag(timerTag).setStateFamily(stateFamily).setTimestamp(timerTimestamp).setType(Windmill.Timer.Type.WATERMARK).build())));
    assertThat(actualOutput.getListUpdatesList(), Matchers.contains(Matchers.equalTo(Windmill.TagList.newBuilder().setTag(bufferTag).setStateFamily(stateFamily).addValues(Windmill.Value.newBuilder().setTimestamp(Long.MAX_VALUE).setData(bufferData).build()).build())));
    assertThat(actualOutput.getWatermarkHoldsList(), Matchers.contains(Matchers.equalTo(Windmill.WatermarkHold.newBuilder().setTag(watermarkHoldTag).setStateFamily(stateFamily).addTimestamps(0).build())));
    List<Windmill.Counter> counters = actualOutput.getCounterUpdatesList();
    // No state reads
    assertEquals(0L, getCounter(counters, "WindmillStateBytesRead").getIntScalar());
    // Timer + buffer + watermark hold
    assertEquals(Windmill.WorkItemCommitRequest.newBuilder(actualOutput).clearCounterUpdates().clearOutputMessages().build().getSerializedSize(), getCounter(counters, "WindmillStateBytesWritten").getIntScalar());
    // Input messages
    assertEquals(VarInt.getLength(0L) + dataStringForIndex(0).length() + addPaneTag(PaneInfo.NO_FIRING, windowAtZeroBytes()).size() + 5L, /* proto overhead */
    getCounter(counters, "WindmillShuffleBytesRead").getIntScalar());
    Windmill.GetWorkResponse.Builder getWorkResponse = Windmill.GetWorkResponse.newBuilder();
    getWorkResponse.addWorkBuilder().setComputationId(DEFAULT_COMPUTATION_ID).setInputDataWatermark(timerTimestamp).addWorkBuilder().setKey(ByteString.copyFromUtf8(DEFAULT_KEY_STRING)).setWorkToken(1).getTimersBuilder().addTimersBuilder().setTag(timerTag).setStateFamily(stateFamily).setTimestamp(timerTimestamp);
    server.addWorkToOffer(getWorkResponse.build());
    long expectedBytesRead = 0L;
    Windmill.GetDataResponse.Builder dataResponse = Windmill.GetDataResponse.newBuilder();
    Windmill.KeyedGetDataResponse.Builder dataBuilder = dataResponse.addDataBuilder().setComputationId(DEFAULT_COMPUTATION_ID).addDataBuilder().setKey(ByteString.copyFromUtf8(DEFAULT_KEY_STRING));
    dataBuilder.addListsBuilder().setTag(bufferTag).setStateFamily(stateFamily).addValuesBuilder().setTimestamp(// is ignored
    0).setData(bufferData);
    dataBuilder.addWatermarkHoldsBuilder().setTag(watermarkHoldTag).setStateFamily(stateFamily).addTimestamps(0);
    dataBuilder.addValuesBuilder().setTag(paneInfoTag).setStateFamily(stateFamily).getValueBuilder().setTimestamp(0).setData(ByteString.EMPTY);
    server.addDataToOffer(dataResponse.build());
    expectedBytesRead += dataBuilder.build().getSerializedSize();
    result = server.waitForAndGetCommits(1);
    actualOutput = result.get(1L);
    assertEquals(1, actualOutput.getOutputMessagesCount());
    assertEquals(DEFAULT_DESTINATION_STREAM_ID, actualOutput.getOutputMessages(0).getDestinationStreamId());
    assertEquals(DEFAULT_KEY_STRING, actualOutput.getOutputMessages(0).getBundles(0).getKey().toStringUtf8());
    assertEquals(0, actualOutput.getOutputMessages(0).getBundles(0).getMessages(0).getTimestamp());
    assertEquals(outputData, actualOutput.getOutputMessages(0).getBundles(0).getMessages(0).getData());
    ByteString metadata = actualOutput.getOutputMessages(0).getBundles(0).getMessages(0).getMetadata();
    assertEquals(PaneInfo.createPane(true, true, Timing.ON_TIME), PaneInfo.decodePane(metadata.byteAt(0)));
