    // Test recovery.
    server.addWorkToOffer(buildInput("work {" + "  computation_id: \"computation\"" + "  input_data_watermark: 0" + "  work {" + "    key: \"0000000000000002\"" + "    work_token: 3" + "    source_state {" + "      state: \"\005\"" + "    } " + "  }" + "}", null));
