    Mockito.verify(mockExecutor).forceExecute(Mockito.<Runnable>any());
    activeWork.completeWork(key1);
    assertEquals(true, activeWork.activateWork(key1, new MockWork(1)));
    activeWork.completeWork(key1);
}

