        // Returned a record that starts at position 0 of 40 - 1/40 fraction consumed.
        assertEquals(1.0f / 40, progress.getPercentComplete(), 1e-6);
        iterator.next();
        iterator.next();
        progress = readerProgressToCloudProgress(iterator.getProgress());
