@Test
public void testAfterAllRealTriggersFixedWindow() throws Exception {
    tester = TriggerTester.nonCombining(FixedWindows.of(Duration.millis(50)), Repeatedly.<IntervalWindow>forever(AfterAll.<IntervalWindow>of(AfterPane.<IntervalWindow>elementCountAtLeast(5), AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(5)))), AccumulationMode.DISCARDING_FIRED_PANES, Duration.millis(100));
    tester.advanceProcessingTime(new Instant(0));
    // 6 elements -> after pane fires
    tester.injectElements(TimestampedValue.of(0, new Instant(0)), TimestampedValue.of(1, new Instant(0)), TimestampedValue.of(2, new Instant(1)), TimestampedValue.of(3, new Instant(1)), TimestampedValue.of(4, new Instant(1)), TimestampedValue.of(5, new Instant(2)));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
    tester.advanceProcessingTime(new Instant(5));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(0, 1, 2, 3, 4, 5), 0, 0, 50)));
    // 4 elements, advance processing time, then deliver the last elem
    tester.advanceProcessingTime(new Instant(15));
    tester.injectElements(TimestampedValue.of(6, new Instant(2)), TimestampedValue.of(7, new Instant(3)), TimestampedValue.of(8, new Instant(4)), TimestampedValue.of(9, new Instant(5)));
    tester.advanceProcessingTime(new Instant(20));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
    tester.injectElements(TimestampedValue.of(10, new Instant(6)));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(6, 7, 8, 9, 10), 2, 0, 50)));
    assertFalse(tester.isMarkedFinished(new IntervalWindow(new Instant(0), new Instant(50))));
    // We're holding some finished bits, but that should be it.
    tester.assertHasOnlyGlobalAndFinishedSetsAndPaneInfoFor(new IntervalWindow(new Instant(0), new Instant(50)));
}

@Test
public void testAfterAllMergingWindowSomeFinished() throws Exception {
    Duration windowDuration = Duration.millis(10);
    TriggerTester<Integer, Iterable<Integer>, IntervalWindow> tester = TriggerTester.nonCombining(Sessions.withGapDuration(windowDuration), AfterAll.<IntervalWindow>of(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(5)), AfterPane.<IntervalWindow>elementCountAtLeast(5)), AccumulationMode.ACCUMULATING_FIRED_PANES, Duration.millis(100));
    tester.advanceProcessingTime(new Instant(10));
    tester.injectElements(// in [1, 11), timer for 15
    TimestampedValue.of(1, new Instant(1)));
    tester.advanceProcessingTime(new Instant(15));
    tester.injectElements(// in [1, 11) count = 1
    TimestampedValue.of(2, new Instant(1)), // in [2, 12), timer for 16
    TimestampedValue.of(3, new Instant(2)));
    // Enough data comes in for 2 that combined, we should fire
    tester.injectElements(TimestampedValue.of(4, new Instant(2)), TimestampedValue.of(5, new Instant(2)));
    // This fires, because the earliest element in [1, 12) arrived at time 10
    assertThat(tester.extractOutput(), Matchers.contains(WindowMatchers.isSingleWindowedValue(Matchers.containsInAnyOrder(1, 2, 3, 4, 5), 1, 1, 12)));
    assertTrue(tester.isMarkedFinished(new IntervalWindow(new Instant(1), new Instant(12))));
    tester.assertHasOnlyGlobalAndFinishedSetsFor(new IntervalWindow(new Instant(1), new Instant(12)));
}

