    tester.injectElements(TimestampedValue.of(4, new Instant(1)), TimestampedValue.of(5, new Instant(2)), // count = 5, but need to call merge fire
    TimestampedValue.of(6, new Instant(1)));
    // This fires, because the earliest element in [1, 12) arrived at time 10
    assertThat(tester.extractOutput(), Matchers.contains(WindowMatchers.isSingleWindowedValue(Matchers.containsInAnyOrder(1, 2, 3, 4, 5, 6), 1, 1, 12)));
    assertTrue(tester.isMarkedFinished(new IntervalWindow(new Instant(1), new Instant(12))));
    tester.assertHasOnlyGlobalAndFinishedSetsFor(new IntervalWindow(new Instant(1), new Instant(12)));
}

