@Test
public void testAfterFirstRealTriggersFixedWindow() throws Exception {
    tester = TriggerTester.nonCombining(FixedWindows.of(Duration.millis(50)), Repeatedly.<IntervalWindow>forever(AfterFirst.<IntervalWindow>of(AfterPane.<IntervalWindow>elementCountAtLeast(5), AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(5)))), AccumulationMode.DISCARDING_FIRED_PANES, Duration.millis(100));
    tester.advanceProcessingTime(new Instant(0));
    // 5 elements -> after pane fires
    tester.injectElements(TimestampedValue.of(0, new Instant(0)), TimestampedValue.of(1, new Instant(0)), TimestampedValue.of(2, new Instant(1)), TimestampedValue.of(3, new Instant(1)), TimestampedValue.of(4, new Instant(1)));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(0, 1, 2, 3, 4), 0, 0, 50)));
    // 4 elements, advance processing time to 5 (shouldn't fire yet), then advance it to 6
    tester.advanceProcessingTime(new Instant(1));
    tester.injectElements(TimestampedValue.of(5, new Instant(2)), TimestampedValue.of(6, new Instant(3)), TimestampedValue.of(7, new Instant(4)), TimestampedValue.of(8, new Instant(5)));
    tester.advanceProcessingTime(new Instant(5));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
    tester.advanceProcessingTime(new Instant(6));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(5, 6, 7, 8), 2, 0, 50)));
    // Now, send in 5 more elements, and make sure they come out as a group. State should not
    // be carried over.
    tester.injectElements(TimestampedValue.of(9, new Instant(6)), TimestampedValue.of(10, new Instant(7)), TimestampedValue.of(11, new Instant(8)), TimestampedValue.of(12, new Instant(9)), TimestampedValue.of(13, new Instant(10)));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(9, 10, 11, 12, 13), 6, 0, 50)));
    assertFalse(tester.isMarkedFinished(new IntervalWindow(new Instant(0), new Instant(50))));
    // Because none of the triggers ever stay finished (we always immediately reset) there is no
    // persisted per-window state. But there may be pane-info.
    tester.assertHasOnlyGlobalAndPaneInfoFor(new IntervalWindow(new Instant(0), new Instant(50)));
}

