@Test
public void testOrFinallyRealTriggersFixedWindow() throws Exception {
    // Test an orFinally with a composite trigger, and make sure it properly resets state, etc.
    tester = TriggerTester.nonCombining(FixedWindows.of(Duration.millis(50)), Repeatedly.<IntervalWindow>forever(// This element count should never fire because the orFinally fires sooner, every time
    AfterPane.<IntervalWindow>elementCountAtLeast(12).orFinally(AfterAll.<IntervalWindow>of(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(5)), AfterPane.<IntervalWindow>elementCountAtLeast(5)))), AccumulationMode.DISCARDING_FIRED_PANES, Duration.millis(100));
    // First, fire processing time then the 5 element
    tester.advanceProcessingTime(new Instant(0));
    tester.injectElements(TimestampedValue.of(0, new Instant(0)), TimestampedValue.of(1, new Instant(0)), TimestampedValue.of(2, new Instant(1)), TimestampedValue.of(3, new Instant(1)));
    tester.advanceProcessingTime(new Instant(5));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
    tester.injectElements(TimestampedValue.of(4, new Instant(1)));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(0, 1, 2, 3, 4), 0, 0, 50)));
    tester.assertHasOnlyGlobalAndPaneInfoFor(new IntervalWindow(new Instant(0), new Instant(50)));
    // Then fire 6 new elements, then processing time
    tester.injectElements(TimestampedValue.of(6, new Instant(2)), TimestampedValue.of(7, new Instant(3)), TimestampedValue.of(8, new Instant(4)), TimestampedValue.of(9, new Instant(5)), TimestampedValue.of(10, new Instant(2)), TimestampedValue.of(11, new Instant(3)));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
    tester.advanceProcessingTime(new Instant(15));
    assertThat(tester.extractOutput(), Matchers.contains(isSingleWindowedValue(Matchers.containsInAnyOrder(6, 7, 8, 9, 10, 11), 2, 0, 50)));
    // Finally, fire 3 more elements and verify the base of the orFinally doesn't fire.
    TimestampedValue.of(100, new Instant(1));
    TimestampedValue.of(101, new Instant(1));
    TimestampedValue.of(102, new Instant(1));
    assertThat(tester.extractOutput(), Matchers.emptyIterable());
}

@Test
public void testOrFinallyMergingWindowSomeFinished() throws Exception {
    Duration windowDuration = Duration.millis(10);
    TriggerTester<Integer, Iterable<Integer>, IntervalWindow> tester = TriggerTester.nonCombining(Sessions.withGapDuration(windowDuration), AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(5)).orFinally(AfterPane.<IntervalWindow>elementCountAtLeast(5)), AccumulationMode.ACCUMULATING_FIRED_PANES, Duration.millis(100));
    tester.advanceProcessingTime(new Instant(10));
    tester.injectElements(// in [1, 11), timer for 15
    TimestampedValue.of(1, new Instant(1)), // in [1, 11) count = 1
    TimestampedValue.of(2, new Instant(1)), // in [2, 12), timer for 16
    TimestampedValue.of(3, new Instant(2)));
    // Enough data comes in for 2 that combined, we should fire
    tester.injectElements(TimestampedValue.of(4, new Instant(2)), TimestampedValue.of(5, new Instant(2)));
    // This fires, because the earliest element in [1, 12) arrived at time 10
    assertThat(tester.extractOutput(), Matchers.contains(WindowMatchers.isSingleWindowedValue(Matchers.containsInAnyOrder(1, 2, 3, 4, 5), 1, 1, 12)));
    assertTrue(tester.isMarkedFinished(new IntervalWindow(new Instant(1), new Instant(12))));
    tester.assertHasOnlyGlobalAndFinishedSetsFor(new IntervalWindow(new Instant(1), new Instant(12)));
}

