@Test
public void testOurApiSurface() throws Exception {
    ApiSurface checkedApiSurface = ApiSurface.getSdkApiSurface().pruningClassName("com.google.cloud.dataflow.sdk.runners.worker.StateFetcher").pruningClassName("com.google.cloud.dataflow.sdk.util.common.ReflectHelpers").pruningClassName("com.google.cloud.dataflow.sdk.TestUtils").pruningClassName("com.google.cloud.dataflow.sdk.WindowMatchers");
    checkedApiSurface.getExposedClasses();
    Map<Class<?>, List<Class<?>>> disallowedClasses = Maps.newHashMap();
    for (Class<?> clazz : checkedApiSurface.getExposedClasses()) {
        if (!classIsAllowed(clazz)) {
            disallowedClasses.put(clazz, checkedApiSurface.getAnyExposurePath(clazz));
        }
    }
    List<String> disallowedMessages = Lists.newArrayList();
    for (Map.Entry<Class<?>, List<Class<?>>> entry : disallowedClasses.entrySet()) {
        disallowedMessages.add(entry.getKey() + " exposed via:\n\t\t" + Joiner.on("\n\t\t").join(entry.getValue()));
    }
    Collections.sort(disallowedMessages);
    if (!disallowedMessages.isEmpty()) {
        fail("The following disallowed classes appear in the public API surface of the SDK:\n\t" + Joiner.on("\n\t").join(disallowedMessages));
    }
}

