@Test
public void testThatResettingAllowsReuse() throws Exception {
    AttemptBoundedExponentialBackOff backOff = new AttemptAndTimeBoundedExponentialBackOff(3, 500, 1000L, AttemptAndTimeBoundedExponentialBackOff.ResetPolicy.ALL, fastClock);
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(249L), lessThan(751L)));
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(374L), lessThan(1126L)));
    assertEquals(BackOff.STOP, backOff.nextBackOffMillis());
    backOff.reset();
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(249L), lessThan(751L)));
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(374L), lessThan(1126L)));
    assertEquals(BackOff.STOP, backOff.nextBackOffMillis());
    backOff = new AttemptAndTimeBoundedExponentialBackOff(30, 500, 1000L, AttemptAndTimeBoundedExponentialBackOff.ResetPolicy.ALL, fastClock);
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(249L), lessThan(751L)));
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(374L), lessThan(1126L)));
    fastClock.sleep(2000L);
    assertEquals(BackOff.STOP, backOff.nextBackOffMillis());
    backOff.reset();
    assertThat(backOff.nextBackOffMillis(), allOf(greaterThan(249L), lessThan(751L)));
}

