/**
 * Test that we receive an empty on-time pane when an or-finally waiting for the watermark fires.
 * Specifically, verify the proper triggerings and pane-info of a typical speculative/on-time/late
 * when the on-time pane is empty.
 */
@Test
public void testEmptyOnTimeFromOrFinally() throws Exception {
    TriggerTester<Integer, Integer, IntervalWindow> tester = TriggerTester.combining(FixedWindows.of(Duration.millis(10)), AfterEach.<IntervalWindow>inOrder(Repeatedly.<IntervalWindow>forever(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(new Duration(5))).orFinally(AfterWatermark.<IntervalWindow>pastEndOfWindow()), Repeatedly.<IntervalWindow>forever(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(new Duration(25)))), AccumulationMode.ACCUMULATING_FIRED_PANES, new Sum.SumIntegerFn().<String>asKeyedFn(), VarIntCoder.of(), Duration.millis(100));
    tester.advanceWatermark(new Instant(0));
