/**
 * Tests for processing time firings after the watermark passes the end of the window.
 * Specifically, verify the proper triggerings and pane-info of a typical speculative/on-time/late
 * when the on-time pane is non-empty.
 */
@Test
public void testProcessingTime() throws Exception {
    TriggerTester<Integer, Integer, IntervalWindow> tester = TriggerTester.combining(FixedWindows.of(Duration.millis(10)), AfterEach.<IntervalWindow>inOrder(Repeatedly.<IntervalWindow>forever(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(new Duration(5))).orFinally(AfterWatermark.<IntervalWindow>pastEndOfWindow()), Repeatedly.<IntervalWindow>forever(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(new Duration(25)))), AccumulationMode.ACCUMULATING_FIRED_PANES, new Sum.SumIntegerFn().<String>asKeyedFn(), VarIntCoder.of(), Duration.millis(100));
    tester.advanceWatermark(new Instant(0));
    tester.advanceProcessingTime(new Instant(0));
    tester.injectElements(TimestampedValue.of(1, new Instant(1)), TimestampedValue.of(1, new Instant(3)), TimestampedValue.of(1, new Instant(7)), TimestampedValue.of(1, new Instant(5)));
    tester.advanceProcessingTime(new Instant(5));
    tester.injectElements(TimestampedValue.of(1, new Instant(8)), TimestampedValue.of(1, new Instant(4)));
    tester.advanceWatermark(new Instant(11));
    tester.injectElements(TimestampedValue.of(1, new Instant(8)), TimestampedValue.of(1, new Instant(4)), TimestampedValue.of(1, new Instant(5)));
    tester.advanceWatermark(new Instant(12));
    tester.injectElements(TimestampedValue.of(1, new Instant(3)));
    tester.advanceProcessingTime(new Instant(15));
    tester.injectElements(TimestampedValue.of(1, new Instant(5)));
    tester.advanceProcessingTime(new Instant(30));
    tester.injectElements(TimestampedValue.of(1, new Instant(3)));
    tester.advanceWatermark(new Instant(125));
    List<WindowedValue<Integer>> output = tester.extractOutput();
    assertEquals(4, output.size());
    assertThat(output.get(0), WindowMatchers.isSingleWindowedValue(4, 1, 0, 10));
    assertThat(output.get(1), WindowMatchers.isSingleWindowedValue(6, 4, 0, 10));
    assertThat(output.get(2), WindowMatchers.isSingleWindowedValue(11, 9, 0, 10));
    assertThat(output.get(3), WindowMatchers.isSingleWindowedValue(12, 9, 0, 10));
    assertThat(output.get(0), WindowMatchers.valueWithPaneInfo(PaneInfo.createPane(true, false, Timing.EARLY, 0, -1)));
    assertThat(output.get(1), WindowMatchers.valueWithPaneInfo(PaneInfo.createPane(false, false, Timing.ON_TIME, 1, 0)));
    assertThat(output.get(2), WindowMatchers.valueWithPaneInfo(PaneInfo.createPane(false, false, Timing.LATE, 2, 1)));
    assertThat(output.get(3), WindowMatchers.valueWithPaneInfo(PaneInfo.createPane(false, true, Timing.LATE, 3, 2)));
}

@Test
public void testMultipleTimerTypes() throws Exception {
    Trigger<IntervalWindow> trigger = spy(Repeatedly.forever(AfterFirst.of(AfterProcessingTime.<IntervalWindow>pastFirstElementInPane().plusDelayOf(Duration.millis(10)), AfterWatermark.<IntervalWindow>pastEndOfWindow())));
    TriggerTester<Integer, Iterable<Integer>, IntervalWindow> tester = TriggerTester.nonCombining(FixedWindows.of(Duration.millis(10)), trigger, AccumulationMode.DISCARDING_FIRED_PANES, Duration.standardDays(1));
    tester.injectElements(TimestampedValue.of(1, new Instant(1)));
    ResultCaptor<TriggerResult> result = new ResultCaptor<>();
    doAnswer(result).when(trigger).onTimer(Mockito.<Trigger<IntervalWindow>.OnTimerContext>any());
    tester.advanceWatermark(new Instant(1000));
    assertEquals(TriggerResult.FIRE, result.get());
    tester.advanceProcessingTime(Instant.now().plus(Duration.millis(10)));
    // Verify that the only onTimer call was the one from advancing the watermark.
    verify(trigger).onTimer(Mockito.<Trigger<IntervalWindow>.OnTimerContext>any());
}

