@Test
public void testParDoWithNoSideOutputsErrorDoesNotMentionTupleTag() {
    Pipeline p = TestPipeline.create();
    PCollection<EmptyClass> input = p.apply(Create.of(1, 2, 3)).apply(ParDo.of(new EmptyClassDoFn()));
    try {
        input.getCoder();
    } catch (IllegalStateException exc) {
        String message = exc.getMessage();
        // Output specific to ParDo TupleTag side outputs should not be present.
        assertThat(message, not(containsString("erasure")));
        assertThat(message, not(containsString("see TupleTag Javadoc")));
        // Instead, expect output suggesting other possible fixes.
        assertThat(message, containsString("Building a Coder using a registered CoderFactory failed"));
        assertThat(message, containsString("Building a Coder from the @DefaultCoder annotation failed"));
        assertThat(message, containsString("Building a Coder from the fallback CoderProvider failed"));
        return;
    }
    fail("Should have thrown IllegalStateException due to failure to infer a coder.");
}

